insert into public.products (slug, name, kind, headline, headline_em, headline_style, description, highlights, cta_label, cta_url, site_url, accent_dark, accent_light, button_dark, button_light, status, sort_order)
values ($c$zeno$c$, $c$Zeno$c$, $c$Split the bill, item by item$c$, $c$Every line,$c$, $c$fairly yours.$c$, $c$serif$c$, $c$Snap any receipt. Zeno shares the GST, service charge and discounts by what each person ordered, and sends everyone their part. No sign-up needed to start.$c$, $c$[{"label":"Split","value":"By item"},{"label":"Friends","value":"No app needed"},{"label":"Receipt photo","value":"Never stored"}]$c$::jsonb, $c$Scan a receipt$c$, $c$https://zenoapp.midnightpoetry.studio/scan$c$, $c$https://zeno.midnightpoetry.studio/$c$, $c$#F0A684$c$, $c$#A04A2A$c$, $c$#F8F0E1$c$, $c$#1F1D1A$c$, 'live', 2)
on conflict (slug) do nothing;

