insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$split-gst-service-charge$c$, $c$How to split GST and service charge fairly$c$, $c$An even split overcharges whoever ordered least. Here is the order receipts usually apply charges in, and how to share each one by what people actually ate.$c$, $c$[{"type":"callout","title":"The short version","text":"Share every discount, service charge and GST by each person's share of the food, not by headcount. On a typical restaurant receipt, the discount comes off first, service charge is added next, and GST is charged on both."},{"type":"heading","text":"Why an even split isn't fair"},{"type":"paragraph","text":"Three friends share a $129.49 dinner. Split evenly, each pays about $43.16. But Ben only had chicken rice, his share of the satay and teh tarik, and half a chendol. By what he actually ordered, he owes $36.51 — so an even split quietly charges him $6.65 for food he never ate."},{"type":"heading","text":"The order charges are applied"},{"type":"table","caption":"How a typical receipt adds up.","header":["Line","Amount"],"rows":[["Subtotal","120.00"],["Member discount 10%","-12.00"],["Service charge 10% on 108.00","10.80"],["GST 9% on 118.80","10.69"],["Total","129.49"]]},{"type":"paragraph","text":"Because every charge is a percentage of the food, each person's share of the charges is simply their share of the food. Work out what each person ordered, then scale it by the same factor the receipt used."},{"type":"heading","text":"A worked example"},{"type":"table","caption":"Shared dishes are divided between the people who had them.","header":["Person","What they had","Food","Pays"],"rows":[["Alicia","Laksa, grilled fish, ⅓ satay, ⅓ teh tarik, ½ chendol","51.83","55.93"],["Ben","Chicken rice, ⅓ satay, ⅓ teh tarik, ½ chendol","33.83","36.51"],["Chen","Nasi lemak, kopi C, ⅓ satay, ⅓ teh tarik","34.33","37.05"]]},{"type":"paragraph","text":"Each person's food is multiplied by 0.9 for the discount, 1.1 for service charge and 1.09 for GST. The three amounts add back up to the $129.49 on the receipt."},{"type":"heading","text":"When the cents don't divide"},{"type":"paragraph","text":"A $28.00 platter shared three ways is $9.333… each. Round two shares down and give the leftover cent to the third person, so the total still matches the receipt to the cent."},{"type":"heading","text":"Common questions"},{"type":"faq","items":[{"q":"Is GST charged on the service charge?","a":"On a typical restaurant bill with GST, yes: GST is worked out on the food plus the service charge, which is why it comes last."},{"q":"What if a discount only applies to one dish?","a":"Take it off that dish first, then share the dish as usual."},{"q":"Do my friends need Zeno to see the split?","a":"No. They get a picture of who owes what and why, and settle up however your group usually does."}]},{"type":"cta","title":"Let the monkey do the maths.","text":"No sign-up needed to start.","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, true, $c$How to split GST and service charge fairly | Zeno$c$, $c$Why an even split overcharges the light eater, the order receipts apply discounts, service charge and GST in, and a worked example.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$fair-splits$c$
where p.slug = $c$zeno$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$even-split-or-itemised$c$, $c$Even split or itemised? When each one is fair$c$, $c$Splitting evenly is quick and sometimes exactly right. Here is how to tell when it is, and how to switch between the two in Zeno.$c$, $c$[{"type":"callout","title":"The short version","text":"Split evenly when everyone shared everything, or when the difference is too small to matter to your group. Split by item when people ordered different things — especially when one person skipped the drinks or the dessert."},{"type":"heading","text":"When an even split is fair"},{"type":"list","ordered":false,"items":["Everyone shared every dish, family style.","Everyone ordered roughly the same thing, like a set menu.","The group has agreed it doesn't mind a few dollars either way."]},{"type":"heading","text":"When it isn't"},{"type":"paragraph","text":"An even split adds up everyone's food and divides it by headcount, so whoever ordered least pays for part of someone else's meal. The gap grows with the bill: one person skipping a round of cocktails can easily be $20 out of pocket. Discounts, service charge and tax make it worse, because they are percentages of the food — an even split shares those evenly too."},{"type":"table","caption":"The same $100 dinner for two, split both ways.","header":["Person","Ate","Even split","By item"],"rows":[["Mei","$70 of food","$50","$70"],["Jun","$30 of food","$50","$30"]]},{"type":"heading","text":"Switching in Zeno"},{"type":"list","ordered":true,"items":["Scan the receipt and check it on the **Check the receipt** screen.","On **Who had what?**, use the toggle at the top: **By item** or **Split equally**.","With **By item**, tap each person's dot on the things they had. With **Split equally**, just add the people.","Tap **Review summary** to see everyone's part, then share it."]},{"type":"paragraph","text":"You can change your mind before you share: switch the toggle and the totals update straight away."},{"type":"heading","text":"Where the odd cent goes"},{"type":"paragraph","text":"When a total doesn't divide evenly, Zeno rounds everyone down to the cent and hands the leftover cents out one at a time, so the shares always add up to the receipt exactly. With an even split, any leftover cent goes to whoever paid the bill."},{"type":"faq","items":[{"q":"Can I split most things evenly but keep one dish separate?","a":"Yes — use **By item**, tap everyone onto the shared dishes, and only the person who had the separate dish onto that one."},{"q":"Does an even split still include service charge and tax?","a":"Yes. The full total on the receipt, charges included, is what gets divided."}]},{"type":"cta","title":"Itemised, not averaged.","text":"Scan your next receipt and see the difference.","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, false, $c$Even split or itemised bill? When each is fair | Zeno$c$, $c$When an even split is fair, when it quietly overcharges someone, and how to switch between By item and Split equally in Zeno.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$fair-splits$c$
where p.slug = $c$zeno$c$
