insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$sharing-a-platter$c$, $c$Sharing a platter between some of the table$c$, $c$The satay was for three of you, the jug of juice for everyone, the cake for two. Here is how to share a dish between just the people who had it.$c$, $c$[{"type":"callout","title":"The short version","text":"On **Who had what?**, tap every person who shared the dish. Zeno divides that line equally between them and shows “Shared by 3 · $4.00 each” under it."},{"type":"heading","text":"Sharing a line"},{"type":"list","ordered":true,"items":["Make sure **By item** is selected at the top of **Who had what?**.","Find the shared dish and tap the dot of each person who had some.","Check the line now reads “Shared by N” with each person's part.","With more than three people, tap **All** to put everyone on a line in one go."]},{"type":"paragraph","text":"Each person's charges — discount, service charge and tax — follow their food, so someone who shared a $12 platter three ways pays the charges on $4, not on $12."},{"type":"heading","text":"Uneven portions"},{"type":"paragraph","text":"Zeno shares a line equally between the people tapped on it. If one person clearly had most of a dish, the fairest fix is usually to split it on the receipt first: tap the pencil on the line on the **Check the receipt** screen, lower its quantity or line total, and use **+ Add an item** to add the other portion as its own line."},{"type":"heading","text":"When the cents don't divide"},{"type":"paragraph","text":"A $10.00 jug shared three ways is $3.333… each. Zeno shows $3.33, $3.33 and $3.34, giving the spare cent to someone later in the list, so the first person never pays the extra cent and the line still adds up to $10.00."},{"type":"heading","text":"Things nobody claims"},{"type":"paragraph","text":"Lines nobody has been tapped onto show “Not assigned”, and you can't continue until every line belongs to someone. A quick way to tidy up: tap the person who should take them and choose **Give the N unassigned items to…**."},{"type":"faq","items":[{"q":"How many people can share one bill?","a":"Up to 30 people on a bill."},{"q":"Can a dish be shared by just one person?","a":"Yes — that's simply their dish. Tap only their dot."}]},{"type":"cta","title":"Tap who had what.","text":"Zeno does the dividing.","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, false, $c$Sharing a dish between some of the table | Zeno$c$, $c$How to share a platter, a jug or a dessert between only the people who had it, and how Zeno divides it to the cent.$c$, 'Midnight Poetry Studio', 'published'
