insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$discounts-tips-and-other-charges$c$, $c$Discounts, tips and other charges on the receipt$c$, $c$Vouchers, member discounts, service charge, tax, tips and rounding all change what people owe. Here is how Zeno reads each one and shares it.$c$, $c$[{"type":"callout","title":"The short version","text":"Check the **Discounts, service charge and tax** card before you assign anything. Every charge on it is shared in proportion to each person's items, so the person with the bigger order carries more of the charges and also gets more of the discount."},{"type":"heading","text":"What goes on the card"},{"type":"table","caption":"The charges Zeno understands, in the order they are worked out.","header":["Charge","Worked out on"],"rows":[["Discount (% or amount)","The items, before service charge"],["Service charge %","The items after the discount"],["Tax % (GST, VAT, SST or sales tax)","The items after the discount, plus service charge"],["Tip (% or amount)","The items, after discounts"],["Another charge or rounding","Added as a fixed amount"]]},{"type":"paragraph","text":"Zeno reads these from the receipt when it can. If one is missing or wrong, fill it in on the card — the label shows the right local name for tax."},{"type":"heading","text":"Discounts on one dish"},{"type":"paragraph","text":"A discount on the card is shared across the whole bill. If a voucher only applied to one dish, take it off that dish instead: tap the pencil on the line and lower its **Line total**. Then share the dish as usual."},{"type":"heading","text":"Free items and rounding"},{"type":"list","ordered":false,"items":["A free dessert or birthday dish can stay at $0.00 — assign it to whoever had it, or leave it with the birthday person.","Cash rounding (a few cents up or down) belongs under **+ Another charge or rounding**, so the total matches what you actually paid.","A delivery or corkage fee is also an extra charge — it is shared by each person's items like the rest."]},{"type":"heading","text":"How it is shared"},{"type":"paragraph","text":"Zeno works out the final total with every charge included, then shares it by each person's items in one exact step and rounds only once, at the end. That way the shares always add up to the receipt to the cent, however many charges there are."},{"type":"faq","items":[{"q":"Can I split the tip evenly but the food by item?","a":"Not within one bill — every charge follows each person's items. If your group prefers an even tip, settle the tip separately."},{"q":"The receipt total doesn't match. What now?","a":"The **Check the receipt** screen compares the items and charges with the printed total and tells you the difference. Fix the line or charge that's off, or tap **Use** to accept the total Zeno worked out."}]},{"type":"cta","title":"Every charge, shared fairly.","text":"","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, false, $c$Discounts, tips and charges on a split bill | Zeno$c$, $c$How Zeno applies discounts, service charge, tax, tips and rounding, and why each person's share follows what they ordered.$c$, 'Midnight Poetry Studio', 'published'
