insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$settling-up-without-awkward-messages$c$, $c$Settling up without awkward messages$c$, $c$One message, one picture, no chasing: how Zeno sends everyone their part and what friends see without the app.$c$, $c$[{"type":"callout","title":"The short version","text":"On **Share the bill**, send the itemised picture to your group chat. Everyone sees what they had and what they owe, pays you however your group usually does, and you tap **Mark paid** as it comes in."},{"type":"heading","text":"Send one picture"},{"type":"list","ordered":true,"items":["After **Review summary**, you reach **Share the bill**.","Pick **Chat** for a picture that fits a group chat, or **Story** for a tall one.","Tap **WhatsApp** or **Telegram** to send it straight there, **Save** to keep it in your photos, or **More** for any other app.","Tap **Done** to save the bill."]},{"type":"paragraph","text":"The picture is itemised, uses first names only, and looks the same in light or dark mode. It is drawn on your phone — nothing is uploaded to make it."},{"type":"heading","text":"What your friends need"},{"type":"paragraph","text":"Nothing. They don't need Zeno or an account to read the picture. Because it shows who had what, there is nothing to argue about and no need to explain the maths."},{"type":"heading","text":"Getting paid"},{"type":"paragraph","text":"Zeno never handles money and no payment details are shared. People settle their own way, then you mark them paid. Each person on the bill has a **Mark paid** button, and the bill shows as **Settled** once everyone has paid. In **History**, chips such as **To pay** and **N to settle** show which bills still need attention."},{"type":"heading","text":"A message that doesn't feel like chasing"},{"type":"paragraph","text":"If you do need a nudge, send the picture again from the bill — **Share again** — with a light line like “Here's dinner from Friday, no rush.” The picture does the explaining for you."},{"type":"faq","items":[{"q":"Do I pay my friends through Zeno?","a":"No. Zeno works out the split; you settle up however you normally would."},{"q":"Can someone mark themselves as paid?","a":"Yes, if they are on Zeno and have accepted the bill. Otherwise the person who owns the bill marks them paid."}]},{"type":"cta","title":"One picture. Everyone knows.","text":"","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, true, $c$Settle up a group bill without awkward messages | Zeno$c$, $c$Send one itemised picture to the group chat, let friends pay their own way, and mark people paid as the money comes in.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$settling-up$c$
where p.slug = $c$zeno$c$
