insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$adding-people-to-a-bill$c$, $c$Adding people: names, usernames and Zeno friends$c$, $c$Type a name for anyone, or link people who use Zeno so the bill shows up for them too. Here is the difference.$c$, $c$[{"type":"callout","title":"The short version","text":"Names are quickest and work for everyone. Add someone by **Username** or from **Friends** if they use Zeno and you want the bill to appear in their history too."},{"type":"heading","text":"Three ways to add people"},{"type":"table","caption":"In the **Add people** sheet on **Who had what?**.","header":["Tab","What it does","Who sees the bill"],"rows":[["Names","Type a name and press Enter. Add as many as you like.","Only you — names are saved on this bill"],["Username","Their Zeno username, like @meilin","They get a request to accept"],["Friends","Search people who have accepted a bill from you","They get a request to accept"]]},{"type":"paragraph","text":"Names you've used before appear under **Previously added**, so regulars are one tap away. Requests to linked people are sent when you tap **Done** on the share screen."},{"type":"heading","text":"Inviting someone who isn't on Zeno"},{"type":"paragraph","text":"On the **Friends** tab, choose **Not on Zeno yet? Invite by email**. They get an email with a link that works for 14 days; after they sign in and accept, the bill appears in their history. Zeno never tells you whether an email address already has an account."},{"type":"heading","text":"Linking a name later"},{"type":"paragraph","text":"Started with just a name? Open the saved bill, tap the person and choose **Link Zeno account**, then **Send request**."},{"type":"heading","text":"Paying for the table"},{"type":"paragraph","text":"Tap a person to open their sheet and choose **I paid the bill** (or **{name} paid the bill**). The payer is the one who collects; on an even split, any leftover cent goes to them."},{"type":"faq","items":[{"q":"I'm using Zeno as a guest. Why can I only add names?","a":"Usernames, friends and invites need an account so the request can be sent from you. Create a free account to use them."},{"q":"Can I change someone's name or colour?","a":"Yes — tap the person and edit **Name on the bill** or pick another colour."},{"q":"How many people can be on a bill?","a":"Up to 30."}]},{"type":"cta","title":"Add the table, then tap who had what.","text":"","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, false, $c$Add people to a bill: names, usernames, friends | Zeno$c$, $c$Add people to a Zeno bill by name, by Zeno username or from your friends, or invite them by email — and what each option means.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$settling-up$c$
