insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$when-someone-adds-you-to-a-bill$c$, $c$When someone adds you to a bill$c$, $c$A friend split dinner in Zeno and added you. Here is what you can see, what to tap, and how it counts in your own spending.$c$, $c$[{"type":"callout","title":"The short version","text":"Open **History**, find the card “{name} added you to a bill”, check **Your share**, then tap **Accept** — or **Not me** if it isn't yours."},{"type":"heading","text":"If you got an email"},{"type":"paragraph","text":"The link opens “Someone added you to a bill”. Tap **Continue with email** and sign in (or create a free account). The link works for 14 days."},{"type":"heading","text":"What you can see"},{"type":"paragraph","text":"Only that bill: its items, who had what, and the totals. You never see the other person's other bills, and they never see yours."},{"type":"heading","text":"After you accept"},{"type":"list","ordered":false,"items":["The bill appears under **Shared with you**, and the person who added you becomes a Zeno friend.","Only your share counts towards your own spending — not the whole bill.","If the owner corrects the receipt later, your share updates by itself.","When you've paid them back, you can mark yourself paid."]},{"type":"heading","text":"If it isn't yours"},{"type":"paragraph","text":"Tap **Not me**. The owner sees “Said not me” next to your name and can fix it. Already accepted and don't want it any more? Open the bill and tap **Leave this bill**."},{"type":"faq","items":[{"q":"Do I have to accept to pay my share?","a":"No. Accepting just keeps the bill in your history. You can pay your friend however you like either way."},{"q":"Can I change what I'm down for?","a":"Only the bill's owner can edit it. Let them know and your share updates when they do."}]},{"type":"cta","title":"Your share, and only yours.","text":"","label":"Open Zeno","url":"https://zenoapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Someone added you to a Zeno bill — what now? | Zeno$c$, $c$Accept a shared bill or say it isn't yours, see exactly what you had, mark yourself paid, and leave a bill you no longer need.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$settling-up$c$
where p.slug = $c$zeno$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$scanning-long-faded-or-crumpled-receipts$c$, $c$Scanning long, faded or crumpled receipts$c$, $c$Thermal paper fades, long bills curl and restaurant lighting is dim. A few habits get a clean read almost every time.$c$, $c$[{"type":"callout","title":"The short version","text":"Flatten the receipt on a dark surface, fill the frame, avoid glare, and use **Long bill** for anything longer than your hand. If a read fails, it doesn't use up a scan."},{"type":"heading","text":"Before you tap the shutter"},{"type":"list","ordered":false,"items":["Smooth it flat on the table — a dark table makes the paper's edges stand out.","Fill the frame with the receipt, top to bottom, holding the phone straight above it.","Turn on the flash if the room is dim, but tilt slightly if it causes a bright glare.","Make sure the totals at the bottom are in the picture."]},{"type":"heading","text":"Long receipts"},{"type":"paragraph","text":"Tap **Long bill** on the scan screen before taking the photo. Zeno keeps more detail for tall receipts so small lines stay readable."},{"type":"heading","text":"Using a photo you already took"},{"type":"paragraph","text":"Tap **Photos** to pick one from your phone. Drag and pinch to fit the receipt in the frame, then tap ✓ — or **Another** to choose a different picture."},{"type":"heading","text":"Faded or crumpled paper"},{"type":"paragraph","text":"Faded thermal paper reads best in bright, even light. If parts are unreadable, Zeno flags the lines it wasn't sure about on the next screen so you can fix them in a few taps."},{"type":"heading","text":"If the scan fails"},{"type":"paragraph","text":"You'll see “Zeno couldn't read that receipt. Try a flatter, brighter photo.” Failed reads don't count towards your scans, so just try again. If the receipt is beyond saving, tap **Type it in** and enter the lines yourself."},{"type":"faq","items":[{"q":"Does the photo get stored anywhere?","a":"No. It is resized on your phone with location data removed, read, then deleted."},{"q":"Can I scan from a computer?","a":"Scanning is on your phone. Plus members can add bills by hand on the desktop dashboard."}]},{"type":"cta","title":"Snap it flat, Zeno reads the rest.","text":"","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, false, $c$Scan long, faded or crumpled receipts | Zeno$c$, $c$Tips for getting a clean scan of long, faded or crumpled receipts, using Long bill mode, and what to do when a scan fails.$c$, 'Midnight Poetry Studio', 'published'
