insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$fixing-a-misread-line$c$, $c$Fixing a misread line before you split$c$, $c$Zeno checks the arithmetic and flags anything it wasn't sure about. Here is how to correct a line, add a missing one and make the total match.$c$, $c$[{"type":"callout","title":"The short version","text":"On **Check the receipt**, tap any line flagged in amber, correct it with the pencil, and look for “Matches the total printed on the receipt” before you tap **Looks right · assign items**."},{"type":"heading","text":"Lines Zeno wasn't sure about"},{"type":"paragraph","text":"A banner such as “2 things to check” sits at the top, and the lines in question are marked in amber. Some ask a direct question — “Price unclear: 8.50 or 6.50?” — so you can answer with a glance at the paper."},{"type":"heading","text":"Editing, adding and removing"},{"type":"list","ordered":true,"items":["Tap the pencil on a line to change its **Name**, **Quantity** or **Line total**, then **Save item**.","Tap **+ Add an item** for anything Zeno missed.","Open a line and tap **Remove item** for anything that isn't really an item, like a table number.","Every item needs a name before you can carry on."]},{"type":"heading","text":"Making the total match"},{"type":"paragraph","text":"Zeno adds up the items and charges and compares them with the total printed on the receipt. If they agree you'll see “Matches the total printed on the receipt”. If not, it shows both numbers so you can find the difference — usually a misread price, a missing line or a charge on the **Discounts, service charge and tax** card. If the printed total itself was misread, correct **Total printed on the receipt**, or tap **Use** to accept the total Zeno worked out."},{"type":"heading","text":"The rest of the details"},{"type":"paragraph","text":"The same screen holds the merchant, date, time and a category (Dining, Groceries, Retail, Transport, Travel, Fun or Other), which keep your history tidy. If the photo was hopeless, the camera button **Retake photo** goes back to the scanner."},{"type":"faq","items":[{"q":"Can I edit a bill after I've shared it?","a":"Yes. Open it from **History** and tap the pencil to edit the receipt. People who accepted the bill see their share update."},{"q":"Why does Zeno care if the total matches?","a":"Because everyone's share is worked out from it. A matching total means nobody pays for a misread line."}]},{"type":"cta","title":"Check every line. Then split.","text":"","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, false, $c$Fix a misread receipt line before splitting | Zeno$c$, $c$Correct items Zeno wasn't sure about, add or remove lines, and make the items and charges match the printed total.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$using-zeno$c$
where p.slug = $c$zeno$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$guest-free-or-plus$c$, $c$Guest, free account or Plus: which one you need$c$, $c$You can split tonight's dinner without signing up. Here is what an account adds, what Plus adds, and how to keep the bills you made as a guest.$c$, $c$[{"type":"callout","title":"The short version","text":"Start as a guest to try it tonight. Create a free account to keep your history safe and add friends by username. Get Plus for more scans, the desktop dashboard and monthly reports."},{"type":"table","caption":"Scan allowances are shown on the plan card in **History** as “X of Y scans left this month”.","header":["Feature","Guest","Free account","Plus"],"rows":[["Scans","A few each month","More each month","Many more each month"],["Where bills are kept","This phone only","Your account","Your account, kept for longer"],["Add people","By name","Names, usernames, friends, email","Names, usernames, friends, email"],["Extras","—","—","Desktop dashboard, spending insights, PDF and CSV reports, no ads"]]},{"type":"heading","text":"As a guest"},{"type":"paragraph","text":"Tap **Start as a guest** on the welcome screen. Your bills are saved on this phone only — clear the browser or lose the phone and they're gone. **End guest session** in Account deletes them, and asks first if any bills would be lost."},{"type":"heading","text":"Signing in"},{"type":"paragraph","text":"Zeno emails you a 6-digit code to sign in — tap **Email me a code**, then **Verify and continue**. The code works once and expires after 10 minutes. You can always use your password instead, and you can add an authenticator app in Account › **Security**."},{"type":"heading","text":"Keeping your guest bills"},{"type":"paragraph","text":"Sign in on the same phone and Zeno asks “Move your guest bills?” — tap **Move to account** to keep them, or **Keep on phone**."},{"type":"heading","text":"Out of scans"},{"type":"paragraph","text":"Failed reads never count. If you do run out, you can still **Type it in** by hand, create a free account, or get Plus. Allowances reset each month."},{"type":"faq","items":[{"q":"Do my friends need an account?","a":"No. Only the person splitting the bill needs Zeno."},{"q":"How long are bills kept?","a":"Free accounts keep about three months of history, Plus about five years. The exact periods are in the privacy notice."},{"q":"Can I use Plus on a computer?","a":"Yes — Plus includes a desktop dashboard with your receipts, splits and reports. Scanning stays on your phone."}]},{"type":"cta","title":"Try it tonight. No account needed.","text":"","label":"Open Zeno","url":"https://zenoapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Zeno as a guest, free account or Plus | Zeno$c$, $c$What you can do as a guest, why a free account keeps your bills safe, what Plus adds, and how to move guest bills into an account.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$using-zeno$c$
where p.slug = $c$zeno$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$foreign-currency-receipts$c$, $c$Splitting a receipt in another currency$c$, $c$Dinner abroad, card statement at home. Zeno can split a bill in the currency you'll actually pay back in, using the rate for the receipt date.$c$, $c$[{"type":"callout","title":"The short version","text":"On **Check the receipt**, set **Paid in** to the receipt's currency and **Split in** to the one your group settles in. Zeno fetches the rate for the receipt date — or tap **Edit rate** to use the exact rate from your card statement."},{"type":"heading","text":"Setting the currencies"},{"type":"list","ordered":true,"items":["Scan as usual. On **Check the receipt**, find the currency card.","Set **Paid in** to the currency printed on the receipt.","Set **Split in** to the currency your group will pay back in. It starts as your profile's currency.","Check the rate, then carry on to **Who had what?**."]},{"type":"heading","text":"Which rate to use"},{"type":"paragraph","text":"Zeno looks up the rate for the date on the receipt. Card companies add their own fees, so if you want everyone to repay exactly what your card charged, tap **Edit rate**, type the rate from your statement, and tap **Use this rate**."},{"type":"heading","text":"Cents still add up"},{"type":"paragraph","text":"Converted shares are rounded the same careful way as any other bill, so they add up exactly to the converted total. Currencies without cents, like yen and won, are rounded to whole units."},{"type":"faq","items":[{"q":"How many currencies does Zeno support?","a":"Around three dozen of the most common ones, chosen from the pickers on the currency card."},{"q":"The rate changed after we paid. Can I update it?","a":"Yes. Edit the bill and enter the new rate; everyone's share updates."}]},{"type":"cta","title":"Paid in one, split in another.","text":"","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, false, $c$Split a foreign currency receipt | Zeno$c$, $c$Convert a receipt to your home currency with the rate for the receipt date, use your card's exact rate, and keep shares adding up.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$using-zeno$c$
where p.slug = $c$zeno$c$
