insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$what-happens-to-your-receipt-photo$c$, $c$What happens to your receipt photo$c$, $c$Your receipt is read, then deleted. Here is every step the photo goes through, what Zeno keeps, and how to download or delete your data.$c$, $c$[{"type":"callout","title":"The short version","text":"The photo is resized on your phone with its location data removed, read in memory, and thrown away. Zeno keeps the bill — the lines, people and amounts — not the picture."},{"type":"heading","text":"Step by step"},{"type":"list","ordered":true,"items":["On your phone, Zeno shrinks the photo and re-saves it, which strips the location and camera details stored inside it.","The smaller image is sent over an encrypted connection to be read.","It is read in memory, the lines and totals are checked, and the image is dropped. It is never written to storage.","You check the lines and save the bill."]},{"type":"heading","text":"What Zeno keeps"},{"type":"paragraph","text":"For an account, the bill: merchant, date, items, charges, the people on it and who had what. As a guest, the bill stays on your phone only. The AI service that reads receipts doesn't train on them."},{"type":"heading","text":"The picture you share"},{"type":"paragraph","text":"The itemised picture you send to friends is drawn on your phone and uses first names only. Nothing is uploaded to make it, and no payment details are on it."},{"type":"heading","text":"Download or delete"},{"type":"list","ordered":false,"items":["Account › **Your data and privacy** › **Download my data** gives you everything in your account as a file.","**Delete my account** (type DELETE, then **Delete forever**) removes your account and the bills you own. On bills other people own, you stay as a name only.","As a guest, **End guest session** deletes the bills on your phone."]},{"type":"faq","items":[{"q":"Can people I share a bill with see my other bills?","a":"No. They only see the bill they were added to."},{"q":"How long are bills kept?","a":"For as long as your plan's history lasts, then they are deleted automatically. The privacy notice lists the exact periods."}]},{"type":"cta","title":"Read, then deleted.","text":"Your receipt photo is never stored.","label":"Scan a receipt","url":"https://zenoapp.midnightpoetry.studio/scan"}]$c$::jsonb, false, $c$What happens to your receipt photo | Zeno$c$, $c$How Zeno reads a receipt without storing the photo, what it keeps from the bill, and how to download or delete your data.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$privacy$c$
where p.slug = $c$zeno$c$
on conflict (product_id, slug) do nothing;

