insert into public.products (slug, name, kind, headline, headline_em, headline_style, description, highlights, cta_label, cta_url, site_url, accent_dark, accent_light, button_dark, button_light, status, sort_order)
values ($c$zyra$c$, $c$Zyra$c$, $c$Roster & shift scheduling$c$, $c$Every session covered.$c$, $c$Before anyone asks.$c$, $c$sans$c$, $c$Builds the roster around who is actually free, swaps sessions in two taps and reminds everyone before they're on. Free for small teams; works in any phone browser.$c$, $c$[{"label":"Swaps","value":"Two taps"},{"label":"Double bookings","value":"Blocked"},{"label":"Check-in","value":"QR or code"}]$c$::jsonb, $c$Open Zyra$c$, $c$https://zyra.midnightpoetry.studio/$c$, $c$https://zyra.midnightpoetry.studio/$c$, $c$#A5B0FF$c$, $c$#5546D6$c$, $c$#6E5CF0$c$, $c$#5546D6$c$, 'live', 1)
on conflict (slug) do nothing;

