insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$getting-started-with-zyra$c$, $c$Getting started: your first space in ten minutes$c$, $c$Create a space for your team, add a group for each roster, invite people with a code, and put the first sessions on the calendar.$c$, $c$[{"type":"callout","title":"The short version","text":"Sign up, tap **New space**, invite people from the **People** tab, then add sessions on the **Roster** tab. Everyone sees their sessions as soon as you add them — there's no separate publish step."},{"type":"heading","text":"The words Zyra uses"},{"type":"table","caption":"A quick map before you start.","header":["Word","What it means"],"rows":[["Space","Your organisation — a church, café, club or crew"],["Group","A team inside the space, with its own roster, chat, notices and people"],["Session","One rostered slot on the calendar"],["Position","A role on a session, like Sound, Ushers or Barista"]]},{"type":"heading","text":"1. Create your account"},{"type":"paragraph","text":"Open Zyra in any phone or computer browser and choose **Create your account**. You'll need a password of at least 12 characters, and you'll confirm your email with a link — open it on the same device."},{"type":"heading","text":"2. Create a space"},{"type":"list","ordered":true,"items":["Go to **Spaces**, open the **+** menu and choose **New space**.","Give it a name, a short description and your time zone.","Name the first group (it starts as “Main group”) and pick a calendar type: **Roster** for many people at once, or **Exclusive** for one booking at a time, like a room or a van.","Leave **Leads approve swaps** on if you'd like a lead to check every swap.","Tap **Create space**."]},{"type":"heading","text":"3. Invite your team"},{"type":"paragraph","text":"On the **People** tab, tap **Invite** and choose how many people the invite is for. Zyra gives you a six-character join code and a link to send however you like. See [Inviting people and choosing roles](/guides/zyra/inviting-people-and-roles) for the details."},{"type":"heading","text":"4. Add the first sessions"},{"type":"paragraph","text":"On the **Roster** tab, tap **Add sessions**, pick the people, the position and the dates, and set it to repeat if it happens every week. [Building a fair roster](/guides/zyra/building-a-fair-roster) walks through it."},{"type":"faq","items":[{"q":"Is it free?","a":"Yes for small teams. Each space is free up to a set number of people; larger spaces add seats. See [Plans, seats and Unlimited](/guides/zyra/plans-seats-and-unlimited)."},{"q":"Do people need to install an app?","a":"No. Zyra works in any phone browser. Adding it to the home screen makes it feel like an app and lets it send notifications."}]},{"type":"cta","title":"Every session covered.","text":"Free for small teams. No card needed.","label":"Start free","url":"https://zyraapp.midnightpoetry.studio/sign-up"}]$c$::jsonb, true, $c$Getting started with Zyra: your first roster | Zyra$c$, $c$Create a space, add groups, invite your team with a join code and add your first sessions — a ten-minute set-up for any volunteer or shift team.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$getting-started$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$inviting-people-and-roles$c$, $c$Inviting people and choosing roles$c$, $c$Join codes, invite links, and what Members, Leads and Owners can each do — so the right people can change the roster and everyone else can simply turn up.$c$, $c$[{"type":"callout","title":"The short version","text":"**People** › **Invite** makes a join code and a link that last 7 days. Everyone joins as a Member; promote the people who run the roster to Lead."},{"type":"heading","text":"Making an invite"},{"type":"list","ordered":true,"items":["Open your space and go to the **People** tab.","Tap **Invite** and choose how many people can use it: one person, up to 10, 50 or 200.","Tap **Create invite link**, then **Copy code**, **Copy link**, **Email invite** or **Share**."]},{"type":"paragraph","text":"The code and link are shown only once, so send them straight away. Links expire after 7 days. Codes are six characters and never use 0, O, 1 or I, so they're easy to read aloud at a meeting."},{"type":"heading","text":"Joining"},{"type":"paragraph","text":"With a link, people tap it and choose **Join space**. With a code, they go to **Spaces**, open **+**, choose **Join with a code** and type it in."},{"type":"heading","text":"Roles"},{"type":"table","caption":"Change a role from **People** › the person › Role.","header":["Role","Can"],"rows":[["Member","See the roster, book themselves and swap sessions"],["Lead","Everything a Member can, plus manage the roster, approve swaps and post notices"],["Owner","Everything, including roles for everyone. One owner per space; hand it over when you step back"]]},{"type":"paragraph","text":"Owners and leads are in every group. To choose who else is in a group, open the group's people list and use **Add from the space** or **Take out** — taking someone out releases their upcoming sessions in that group."},{"type":"heading","text":"When someone moves on"},{"type":"paragraph","text":"**Remove from space** on their profile cancels their upcoming sessions, so check the roster afterwards. If you're the owner and stepping back yourself, make someone else owner first — you become a lead."},{"type":"faq","items":[{"q":"Can members invite people too?","a":"Yes, any active member can create an invite. Leads decide who gets which role."},{"q":"What does “This space is full” mean?","a":"The space has used all its seats. The person can tap **Let them know I'm waiting**, and the owner can add seats in Settings. People on Unlimited can always join."}]},{"type":"cta","title":"Bring the whole team in.","text":"","label":"Open Zyra","url":"https://zyraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Invite your team and set roles in Zyra | Zyra$c$, $c$Create a join code or invite link, decide how many people it's for, and give each person the Member, Lead or Owner role.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$getting-started$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$asking-for-availability$c$, $c$Asking for availability without the spreadsheet$c$, $c$Let people mark holidays and unavailable days themselves, so you see clashes while you roster instead of after.$c$, $c$[{"type":"callout","title":"The short version","text":"Ask everyone to add their time off under **Availability and holidays**. When you roster someone who's away, Zyra warns you straight away."},{"type":"heading","text":"For everyone on the team"},{"type":"list","ordered":true,"items":["Open **Availability and holidays**.","Tap **+** and choose **Add time off**.","Pick **Holiday** or **Unavailable**, whole days or a time range, and add a note if it helps.","Save. Only you and your leads can see it."]},{"type":"paragraph","text":"Already keep your holidays in a calendar? Use **Import from a file** with an .ics file, or **Download template** to fill in a spreadsheet and import it as .csv."},{"type":"heading","text":"Space-wide holidays"},{"type":"paragraph","text":"Leads can add dates the whole space is closed on the **Holidays** tab — including public holidays — so nobody gets rostered on them by accident."},{"type":"heading","text":"What leads see"},{"type":"paragraph","text":"When you add a session for someone who's away, Zyra warns you — for example “on holiday then” or “marked themselves unavailable”. It's a warning, not a block: sometimes a person is happy to come in anyway, and you stay in charge."},{"type":"heading","text":"Getting people to actually fill it in"},{"type":"list","ordered":false,"items":["Ask once, with a date: “Please add your holidays for next term by Sunday.”","Post it as a notice on the **Notices** tab so it sits at the top of the space.","Roster after the deadline, and tell people that's how it works — it quickly becomes a habit."]},{"type":"faq","items":[{"q":"Can other members see my time off?","a":"No. Only you and your space's leads see it."},{"q":"Does Zyra build the roster from availability automatically?","a":"Not yet — automatic drafting is on the way. Today you add sessions yourself, with availability warnings shown as you go."}]},{"type":"cta","title":"Fewer clashes, fewer messages.","text":"","label":"Open Zyra","url":"https://zyraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Collect team availability for your roster | Zyra$c$, $c$How your team adds holidays and unavailable days in Zyra, how to import them from a file, and how leads see clashes while rostering.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$rosters$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$building-a-fair-roster$c$, $c$Building a fair roster$c$, $c$Spread the work evenly, respect people's limits, and keep the same few volunteers from carrying everything. Here is how to do it in Zyra.$c$, $c$[{"type":"callout","title":"The short version","text":"Set your positions and rostering limits once in **Settings**, collect availability, then add sessions from the **Roster** tab. Zyra warns you when someone is away, over their limit or rostered on consecutive days, and blocks double bookings outright."},{"type":"heading","text":"Set up once"},{"type":"list","ordered":false,"items":["**Positions** — the roles on a session (Sound, Welcome, Kids, Barista…). Members tick the ones they can do under “Your positions”.","**Rostering limits** — the most sessions per person per day or week, and whether to avoid consecutive days or consecutive weeks.","**Availability** — ask everyone to add their time off first. See [Asking for availability](/guides/zyra/asking-for-availability)."]},{"type":"heading","text":"Adding sessions"},{"type":"list","ordered":true,"items":["On **Roster**, tap **Add sessions**.","Choose the group, then one or more people and the position.","Pick the dates: **One day**, **Date range** or **Pick days**, and a repeat if it's weekly.","Tap **Add session** (or **Add N sessions**). People see them immediately."]},{"type":"heading","text":"What makes a roster feel fair"},{"type":"paragraph","text":"Fair doesn't mean identical — it means nobody quietly does far more than everyone else, and people get a say in when. Rotate the less popular slots, pair new people with experienced ones, and keep an eye on who has said yes most often. The **Dashboard** tab gives owners and leads an overview of the space."},{"type":"heading","text":"Warnings and blocks"},{"type":"table","caption":"Zyra tells you, but leaves most decisions with you.","header":["Situation","What happens"],"rows":[["Person is on holiday or unavailable","Warning"],["Over the most sessions per day or week","Warning"],["Consecutive days or weeks","Warning, if you turned that limit on"],["Person not set up for the position","Warning"],["Same person already booked at that time","Blocked"]]},{"type":"faq","items":[{"q":"Can Zyra draft the roster for me?","a":"Automatic drafting from everyone's availability is coming after launch. For now you place sessions, with Zyra's warnings guiding you."},{"q":"Can I export the roster?","a":"Owners and leads can export from the Dashboard as Excel or PDF."}]},{"type":"cta","title":"A roster people trust.","text":"Free for small teams.","label":"Start free","url":"https://zyraapp.midnightpoetry.studio/sign-up"}]$c$::jsonb, true, $c$How to build a fair volunteer or shift roster | Zyra$c$, $c$Add sessions, set positions and rostering limits, and spot overloaded people early so the same few volunteers don't carry the whole roster.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$rosters$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$recurring-sessions$c$, $c$Weekly and recurring sessions$c$, $c$Sunday services, Saturday shifts, the first Monday of the month: set them up once and change one week without breaking the rest.$c$, $c$[{"type":"callout","title":"The short version","text":"In **Add sessions**, choose a repeat. Later, when you edit a session, choose whether the change applies to **This session**, **This and following** or **All upcoming**."},{"type":"heading","text":"Creating a repeat"},{"type":"list","ordered":true,"items":["On **Roster**, tap **Add sessions** and fill in the group, people and position.","Set the first date, then open the repeat options — from “Don't repeat” through weekly patterns to **Custom…**.","Or use **Pick days** to tap the exact dates when there's no pattern.","Add them all at once. One batch can hold up to 62 sessions — plenty for a year of weekly sessions."]},{"type":"heading","text":"Changing one week"},{"type":"paragraph","text":"Tap the session, choose **Edit**, make the change, then pick **This session**. Only that date changes. Pick **This and following** when something changes for good from a date onward, like a new start time from next month."},{"type":"heading","text":"Cancelling"},{"type":"paragraph","text":"**Cancel session** on a single date is for a one-off — a public holiday or a building closure. If the whole run is ending, edit with **All upcoming** instead."},{"type":"heading","text":"Rotating people through a repeat"},{"type":"paragraph","text":"A rotation (different people each week) is easiest as several repeats: one per person or pair, each every second or fourth week. Zyra's double-booking check stops two repeats from landing the same person twice at the same time."},{"type":"faq","items":[{"q":"Do people get notified about every new session?","a":"They see them on the roster straight away, and get reminders before each one — by default the day before."},{"q":"Can I add one-off events too?","a":"Yes — **Add event** puts something on the calendar that isn't a rostered session, like a team lunch."}]},{"type":"cta","title":"Set it once. Change one week.","text":"","label":"Open Zyra","url":"https://zyraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Set up weekly and recurring sessions | Zyra$c$, $c$Create repeating sessions in one go, pick specific days, and edit one session, this and following, or all upcoming without starting again.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$rosters$c$
where p.slug = $c$zyra$c$
