insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$how-zyra-prevents-double-bookings$c$, $c$How Zyra prevents double bookings$c$, $c$Nobody can be in two places at once, and a room can't hold two bookings. Here is exactly what Zyra blocks, and what it only warns about.$c$, $c$[{"type":"callout","title":"The short version","text":"Zyra refuses any session or swap that would put the same person in two overlapping sessions, and any overlapping booking on an **Exclusive** calendar. Everything else — holidays, limits, positions — is a warning you can choose to override."},{"type":"heading","text":"Two kinds of calendar"},{"type":"table","caption":"Chosen when you create a group.","header":["Calendar","Good for","Overlaps"],"rows":[["Roster","Teams where many people work at once","Different people can overlap; the same person can't"],["Exclusive","A room, a vehicle or a single slot","Only one booking at a time"]]},{"type":"heading","text":"What gets blocked"},{"type":"list","ordered":false,"items":["Adding a session that overlaps one the person already has on that calendar.","Accepting or approving a swap that would double-book someone — you'll see “That swap would double-book someone.”","A second booking at the same time on an Exclusive calendar."]},{"type":"paragraph","text":"The check runs in the database itself, not just on your screen, so two leads adding sessions at the same moment can't sneak a clash past it."},{"type":"heading","text":"What only gets a warning"},{"type":"paragraph","text":"Holidays, “unavailable” days, rostering limits and positions produce warnings. They're real information, but there are good reasons to roster someone anyway, so the decision stays with the lead."},{"type":"faq","items":[{"q":"Can one person be in two different groups' sessions at the same time?","a":"Each group has its own calendar, so check across groups yourself if people serve in more than one team."},{"q":"Why can't a swap go through?","a":"Most often because it would double-book the person taking it. Ask someone else, or adjust one of the sessions first."}]},{"type":"cta","title":"Double bookings, blocked.","text":"","label":"Open Zyra","url":"https://zyraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$How Zyra prevents double bookings | Zyra$c$, $c$What counts as a double booking in Zyra, how roster and exclusive calendars differ, and why swaps can't create clashes either.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$rosters$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$swapping-a-session$c$, $c$Swapping a session without the group chat$c$, $c$Can't make it? Offer your session to the whole space, ask one person directly, or trade with someone — and let Zyra keep the roster right.$c$, $c$[{"type":"callout","title":"The short version","text":"Tap your session, choose **Swap or hand over**, and either **Offer it to the space** (first to accept gets it) or pick a teammate. The roster updates by itself once it's accepted — and approved, if your space asks leads to approve swaps."},{"type":"heading","text":"Giving away your session"},{"type":"list","ordered":true,"items":["Open the session on the **Roster** and tap **Swap or hand over**.","Choose **Offer it to the space**, or a teammate.","Add a note if it helps, then send it.","When someone accepts, the session moves to them."]},{"type":"heading","text":"Asking for someone else's session"},{"type":"paragraph","text":"Tap their session and choose **Ask to swap**. You can offer to **Take it over**, or offer one of your own sessions in return."},{"type":"heading","text":"Answering and approving"},{"type":"paragraph","text":"Everything lives on the **Swaps** tab: **Needs your answer** (accept or decline), **Waiting for your approval** for leads, **Your requests** (withdraw any you no longer need) and **Recent**. If **Leads approve swaps** is on, a swap shows “Waiting for a lead” until a lead approves it."},{"type":"heading","text":"When requests expire"},{"type":"paragraph","text":"A request lasts 48 hours, or until the session starts if that's sooner. Each session can only have one open request at a time, so offers never pile up."},{"type":"faq","items":[{"q":"Can a swap double-book someone?","a":"No. Zyra checks before the swap goes through."},{"q":"Can leads move people around directly?","a":"Yes — leads have **Swap with…** on any session. Owners decide whether leads can also use it on their own sessions."},{"q":"Will the lead know?","a":"Leads can turn on **Tell me when swaps happen** in Settings."}]},{"type":"cta","title":"Swaps, without the scroll.","text":"","label":"Open Zyra","url":"https://zyraapp.midnightpoetry.studio/"}]$c$::jsonb, true, $c$Swap a shift or session without the group chat | Zyra$c$, $c$Offer a session to the space, ask a teammate to take it or trade sessions, how lead approval works, and when swap requests expire.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$swaps-and-cover$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$covering-sick-leave$c$, $c$Covering sick leave at short notice$c$, $c$Someone wakes up unwell. Here is how they tell the team in a moment, how their sessions get offered for cover, and what everyone else sees.$c$, $c$[{"type":"callout","title":"The short version","text":"On **Home**, tap **I'm sick**, choose how long, and tap **Tell my spaces**. Your sessions in that time are offered to others for cover. Tap **I'm back** when you're better."},{"type":"heading","text":"If you're unwell"},{"type":"list","ordered":true,"items":["On **Home**, find “Feeling unwell?” and tap **I'm sick**.","Choose how long: today, or a few days (up to 14).","Add a note for your leads if you like.","Tap **Tell my spaces**."]},{"type":"paragraph","text":"Your sessions in that time are offered to the team — “On leave. Can you cover this shift?” — so you don't have to message anyone yourself."},{"type":"heading","text":"Who sees what"},{"type":"paragraph","text":"Other members only see that you're on leave. Your leads see that it's sick leave, and your note. Health details stay between you and the people who run the roster."},{"type":"heading","text":"For leads"},{"type":"paragraph","text":"If someone tells you directly, open their session and tap **Mark absent or sick**. Choose Absent or Sick leave, and optionally **Give this session to someone else** in the same step."},{"type":"heading","text":"No-shows"},{"type":"paragraph","text":"If your space uses check-in, leads can be told when someone hasn't checked in 10 minutes after a session starts — early enough to find cover. See [QR or code check-in](/guides/zyra/qr-or-code-check-in)."},{"type":"faq","items":[{"q":"What if nobody takes my session?","a":"Your leads can see it's uncovered and reassign it."},{"q":"Do I have to give a reason?","a":"No. The note is optional, and only your leads see it."}]},{"type":"cta","title":"Rest. The roster's covered.","text":"","label":"Open Zyra","url":"https://zyraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Cover sick leave and absences quickly | Zyra$c$, $c$Report sick in Zyra, offer your sessions for cover automatically, and how leads mark someone absent and hand the session on.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$swaps-and-cover$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$reminders-people-read$c$, $c$Reminders people actually read$c$, $c$Phone notifications, Telegram, and a personal nudge from a lead. Set them up once and people stop forgetting their sessions.$c$, $c$[{"type":"callout","title":"The short version","text":"Add Zyra to your home screen, turn on **Send notifications here** under **Me**, and you'll get a reminder the day before each session. Prefer Telegram? Connect it in the same place."},{"type":"heading","text":"1. Add Zyra to your home screen"},{"type":"table","caption":"Notifications on iPhone need the home-screen icon (iOS 16.4 or later).","header":["Device","How"],"rows":[["iPhone","In Safari, tap Share, then **Add to Home Screen**, then Add"],["Android","In Chrome, tap **Install app**"],["Computer","Use the install icon in the address bar, or in Safari, File › Add to Dock"]]},{"type":"heading","text":"2. Turn on notifications"},{"type":"paragraph","text":"Open Zyra from the home-screen icon, go to **Me**, and switch on **Send notifications here**. Allow notifications when your phone asks, then tap **Send a test** to check."},{"type":"heading","text":"3. Or use Telegram"},{"type":"paragraph","text":"Under **Me**, enter your Telegram username, tap **Connect Telegram**, and press Start in the Zyra bot within 15 minutes. Then choose where notifications go: app and Telegram, app only, or Telegram only. Send /stop to the bot any time to disconnect."},{"type":"heading","text":"When reminders arrive"},{"type":"paragraph","text":"By default, one reminder the day before. You can have up to three, anywhere from 14 days before to the start time — and change them for a single session under “Reminders for this session”."},{"type":"heading","text":"A nudge from a lead"},{"type":"paragraph","text":"Leads can tap **Send reminder** on a session to nudge whoever's on it, with a short note like “Doors open at 8:30 this week.” It can be sent once an hour per session, so it never turns into spam."},{"type":"faq","items":[{"q":"Do reminders come by email?","a":"No. Email is only for signing in and account security. Reminders come as phone notifications or Telegram messages."},{"q":"I'm not getting notifications on my iPhone.","a":"Make sure you opened Zyra from the home-screen icon, not Safari, and that notifications are allowed for it in Settings."}]},{"type":"cta","title":"Everyone shows up.","text":"","label":"Open Zyra","url":"https://zyraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Session reminders people actually read | Zyra$c$, $c$Turn on phone notifications, connect Telegram, choose when reminders arrive, and send a teammate a gentle nudge before their session.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$reminders-and-check-in$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$qr-or-code-check-in$c$, $c$QR or code check-in$c$, $c$Know who's actually there without a clipboard. Turn on check-in, show a code at the door, and get told early when someone hasn't arrived.$c$, $c$[{"type":"callout","title":"The short version","text":"In space **Settings** › “Check in and out”, turn the **Check-in button** on. For proof people are really there, add **Ask for a check-in code** and show it from the group's settings with **Show code**."},{"type":"heading","text":"Turning it on"},{"type":"list","ordered":false,"items":["**Check-in button** — Off, On or Required. It appears from an hour before a session until it ends.","**Ask for a check-in code** — a four-character code that changes every 5 minutes, every hour or every day.","**Check the location too** — people must be near the group's venue (50 m to 5 km).","**Check-out button** — for when you also need finishing times.","**Tell me when someone misses one** — leads are told 10 minutes after the start."]},{"type":"heading","text":"At the door"},{"type":"paragraph","text":"A lead opens the group's settings and taps **Show code** (it's also on the Dashboard). People tap **Check in** on their session and type the code, or tap **Scan the QR instead** to scan it from the screen."},{"type":"heading","text":"Forgotten phones"},{"type":"paragraph","text":"If the space allows it, owners and leads can mark someone checked in or out by hand, with a reason, so records stay honest."},{"type":"heading","text":"Privacy"},{"type":"paragraph","text":"With the location check on, Zyra stores only how far someone was from the venue, never their actual position. After five wrong codes in ten minutes, check-in pauses briefly to stop guessing."},{"type":"faq","items":[{"q":"Do people need a separate scanner app?","a":"No. The scanner is built into Zyra."},{"q":"Can I use check-in without codes?","a":"Yes — the button alone works for teams that trust each other and just want a record."}]},{"type":"cta","title":"Who's here, at a glance.","text":"","label":"Open Zyra","url":"https://zyraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$QR code and code check-in for sessions | Zyra$c$, $c$Turn on check-in for a space, show a changing code or QR at the venue, optionally check location, and get alerts when someone misses one.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$reminders-and-check-in$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$plans-seats-and-unlimited$c$, $c$Plans, seats and Unlimited$c$, $c$Free for small teams, seats for bigger spaces, and Unlimited for people who serve in many teams. Here is how the pieces fit.$c$, $c$[{"type":"callout","title":"The short version","text":"Joining and using Zyra is free. A space is free up to a set number of people; beyond that, its owner adds seats. Unlimited is a personal plan for people in lots of groups — and they never take up a seat."},{"type":"heading","text":"Personal plans"},{"type":"table","caption":"See and change yours under **Me** › Plan.","header":["Feature","Free","Unlimited"],"rows":[["Groups","1 group calendar","Unlimited groups and calendars"],["Spaces","Join as many as you like","Join as many as you like"],["Swaps and chat","Included","Included"],["Seats","Uses a seat in a space","Never takes up a seat"],["Ads","One small ad on the home screen","No ads"]]},{"type":"paragraph","text":"Unlimited can be paid monthly or yearly, or once for life when that option is offered. Prices are shown on the Plan screen and on Zyra's pricing page."},{"type":"heading","text":"Seats in a space"},{"type":"paragraph","text":"Each space is free up to a set number of people. When it grows past that, the owner goes to **Settings** › “People and seats” › **Add seats**, one at a time or in packs, charged for the time left in the period. People on Unlimited don't use a seat at all."},{"type":"heading","text":"Managing billing"},{"type":"list","ordered":false,"items":["**Manage billing** under Plan updates your card, switches monthly or yearly, or cancels.","Have a promo code? Enter it under Plan and tap **Apply**.","Cancel a paid plan before deleting your account."]},{"type":"faq","items":[{"q":"Does my whole team need Unlimited?","a":"No. Most members are fine on Free. Unlimited suits people who serve in several groups."},{"q":"What happens if a space is full?","a":"New people see “This space is full” and can let the owner know they're waiting. Adding seats lets them in."}]},{"type":"cta","title":"Free for small teams.","text":"No card needed.","label":"Start free","url":"https://zyraapp.midnightpoetry.studio/sign-up"}]$c$::jsonb, false, $c$Zyra plans: Free, seats and Unlimited | Zyra$c$, $c$What the free plan includes, how seats work when a space grows, what Unlimited adds, and how to pay monthly, yearly or once.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$account-and-plans$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$keeping-your-account-safe$c$, $c$Keeping your account safe$c$, $c$Two-step sign-in is always on in Zyra. Here is how it works, how to use an authenticator app instead of email codes, and how to delete your account.$c$, $c$[{"type":"callout","title":"The short version","text":"On a new device, Zyra emails you a 6-digit code to confirm it's you. Tick **Remember this device** on your own phone. For extra safety, turn on an authenticator app under **Me** › Your account."},{"type":"heading","text":"How two-step sign-in works"},{"type":"paragraph","text":"After your password, a new device shows “Confirm it's you” and Zyra emails a 6-digit code that lasts 10 minutes. Tick **Remember this device** on a phone or computer only you use, and you won't be asked again there for a while."},{"type":"heading","text":"Using an authenticator app"},{"type":"paragraph","text":"Under **Me** › Your account › Authenticator app, tap **Turn on** and scan the code with your authenticator. From then on you can confirm sign-ins with the app instead of waiting for an email."},{"type":"heading","text":"Lost a phone?"},{"type":"list","ordered":false,"items":["Under **Me** › Your account, open **Remembered devices** and forget the lost one.","Tap **Sign out others** to end every session except the one you're using.","Change your password with **Change** — Zyra emails you a link."]},{"type":"heading","text":"Deleting your account"},{"type":"paragraph","text":"Under **Me** › Your account, type DELETE and tap **Schedule deletion**. You have 14 days to change your mind. Cancel any paid plan first. Spaces you own pass to a lead, and your past messages show as “Former member”."},{"type":"faq","items":[{"q":"Can I turn two-step sign-in off?","a":"No. It protects everyone's roster and contact details, so it's always on."},{"q":"I didn't get the code.","a":"Check your spam folder and that the email address is right. Codes expire after 10 minutes, so ask for a new one if it's been a while."}]},{"type":"cta","title":"Safe by default.","text":"","label":"Open Zyra","url":"https://zyraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Two-step sign-in and account safety | Zyra$c$, $c$How Zyra's always-on two-step sign-in works, switching to an authenticator app, managing remembered devices, and deleting your account.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$account-and-plans$c$
where p.slug = $c$zyra$c$
on conflict (product_id, slug) do nothing;
